<script setup lang="ts">
import { localTime, statusLabel } from '../../utils/display'
import type { SourceView } from '../../types/domain'
defineProps<{ sources: readonly SourceView[]; busy: boolean }>()
const emit = defineEmits<{ edit: [source: SourceView]; refresh: [id: string]; toggle: [source: SourceView]; remove: [source: SourceView]; history: [source: SourceView] }>()
</script>
<template><div class="source-grid"><article v-for="source in sources" :key="source.id" class="panel source-card" :data-source-id="source.id">
 <header><div class="source-icon" aria-hidden="true">◎</div><div class="truncate"><h2 :title="source.name">{{ source.name }}</h2><p class="muted truncate">{{ source.hostHint }}</p></div><span class="tag" :class="{ success: source.syncStatus === 'OK' }">{{ statusLabel(source.syncStatus) }}</span></header>
 <div class="source-count"><strong>{{ source.nodeCount }}</strong><span class="muted"> 个节点</span><span class="tag">{{ source.inputFormat === 'AUTO' ? '自动识别' : source.inputFormat }}</span></div>
 <dl><div><dt>连接方式</dt><dd>{{ source.outboundProxy === undefined ? '未读取' : source.outboundProxy ? `可信代理 · ${source.outboundProxy}` : '直接连接' }}</dd></div><div><dt>最近成功</dt><dd>{{ localTime(source.lastSuccessTime) }}</dd></div><div><dt>定时刷新</dt><dd>{{ source.enabled ? `每 ${source.refreshIntervalSeconds / 3600} 小时` : '已暂停' }}</dd></div><div><dt>下次刷新</dt><dd>{{ source.enabled ? localTime(source.nextRefreshTime) : '—' }}</dd></div></dl>
 <p v-if="source.lastErrorCode" class="error">{{ source.lastErrorCode }} · 已保留上次有效节点</p>
 <footer><button class="text-button" :aria-label="`刷新 ${source.name}`" :disabled="busy" @click="emit('refresh', source.id)">↻ 刷新</button><button class="text-button" :aria-label="`编辑 ${source.name}`" :disabled="busy" @click="emit('edit', source)">编辑</button><button class="text-button" :aria-label="`${source.enabled ? '暂停' : '启用'} ${source.name}`" :disabled="busy" @click="emit('toggle', source)">{{ source.enabled ? '暂停' : '启用' }}</button><button class="text-button" @click="emit('history', source)">记录</button><button class="text-button danger" :aria-label="`删除 ${source.name}`" :disabled="busy" @click="emit('remove', source)">删除</button></footer>
</article></div><div v-if="!sources.length" class="panel empty-state"><h2>添加你的第一个订阅</h2><p>多个来源的节点会汇入统一节点池，再由你分配到不同代理组。</p></div></template>
<style scoped>.source-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:18px}.source-card{padding:21px}.source-card header{display:flex;align-items:center;gap:12px}.source-card header>.tag{margin-left:auto}.source-card header h2{overflow:hidden;text-overflow:ellipsis}.source-card header p{font-size:11px;margin-top:4px}.source-icon{display:grid;place-items:center;flex:none;width:38px;height:38px;background:#edf5f1;color:var(--accent);font-size:22px;border-radius:9px}.source-count{display:flex;align-items:baseline;gap:5px;margin:25px 0 18px}.source-count strong{font-size:30px;font-weight:600}.source-count .tag{margin-left:auto}dl{display:grid;gap:9px;margin:0}dl div{display:flex;justify-content:space-between;gap:12px;font-size:11px}dt{color:var(--muted)}dd{margin:0;text-align:right}footer{display:flex;gap:17px;margin-top:22px;padding-top:15px;border-top:1px solid var(--line);font-size:12px}footer .danger{margin-left:auto}.source-card>.error{margin-top:12px}@media(max-width:720px){.source-grid{grid-template-columns:1fr}}</style>
